#!/bin/sh
# Gift Exchange installer for Alpine Linux (OpenRC). Generated by installer/build.sh: the app is the base64
# tarball after the __PAYLOAD_BELOW__ line at the end of this file.
# Re-runnable: replaces /opt/exchange, keeps /var/lib/exchange and /etc/conf.d/exchange, and only adds settings
# that are missing from the config.
#
#   sh setup-exchange.sh                         install / upgrade
#   EXCHANGE_PORT=8771 sh setup-exchange.sh      first install on another port
#   sh setup-exchange.sh --uninstall             remove app and service (keeps data, config and backups)
set -eu

NAME=exchange
DEFAULT_PORT=8770
APP_DIR=/opt/$NAME
DATA_DIR=/var/lib/$NAME
BACKUP_DIR=/var/backups/$NAME
CONF=/etc/conf.d/$NAME
INITD=/etc/init.d/$NAME
LOG=/var/log/$NAME.log
SVC_USER=$NAME
BACKUP_JOB=/etc/periodic/daily/$NAME-backup

UNINSTALL=
case "${1:-}" in
  "") ;;
  --uninstall) UNINSTALL=1 ;;
  *) echo "Unknown argument: $1 (use --uninstall)."; exit 1 ;;
esac

# Household values baked in by build.sh from deploy/deploy.env (first install only; the environment wins).
# __DEPLOY_DEFAULTS__

[ "$(id -u)" = 0 ] || { echo "Run as root."; exit 1; }
command -v apk >/dev/null || { echo "This installer is for Alpine (apk)."; exit 1; }

if [ -n "$UNINSTALL" ]; then
  rc-service "$NAME" stop >/dev/null 2>&1 || true
  rc-update del "$NAME" default >/dev/null 2>&1 || true
  rm -f "$INITD" "$BACKUP_JOB"
  rm -rf "$APP_DIR"
  echo "Removed the app and the backup job. Kept $DATA_DIR, $CONF and $BACKUP_DIR."
  exit 0
fi

conf_val() { sed -n "s/^$1=//p" "$CONF" 2>/dev/null | head -n1 | tr -d "\"'"; }

# An existing install keeps its port.
PORT=${EXCHANGE_PORT:-$DEFAULT_PORT}
[ -f "$CONF" ] && PORT=$(conf_val EXCHANGE_PORT) && PORT=${PORT:-$DEFAULT_PORT}
case "$PORT" in ""|*[!0-9]*) echo "EXCHANGE_PORT must be a number."; exit 1 ;; esac

echo "==> Installing packages"
# sqlite is the sqlite3 command the nightly backup uses; the app itself needs only py3-flask and py3-gunicorn.
apk add --no-cache py3-flask py3-gunicorn sqlite >/dev/null

rc-service "$NAME" stop >/dev/null 2>&1 || true
if netstat -ltn 2>/dev/null | awk '{print $4}' | grep -q ":$PORT\$"; then
  echo "Port $PORT is already in use by something else. Re-run with EXCHANGE_PORT=<free port>."; exit 1
fi

echo "==> Creating user and folders"
# BusyBox adduser -S puts a new user in "nogroup" unless told otherwise, so make the app's own group first.
grep -q "^$SVC_USER:" /etc/group || addgroup -S "$SVC_USER"
id "$SVC_USER" >/dev/null 2>&1 || adduser -S -D -H -h "$DATA_DIR" -s /sbin/nologin -G "$SVC_USER" "$SVC_USER"
mkdir -p "$DATA_DIR" "$BACKUP_DIR"
chmod 700 "$BACKUP_DIR"

echo "==> Unpacking app to $APP_DIR"
TMP=$(mktemp -d /tmp/exchange-tmp.XXXXXX 2>/dev/null || mktemp -d)
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | ( cd "$TMP" && tar -xzf - )
rm -rf "$APP_DIR.new" && mv "$TMP/exchange" "$APP_DIR.new"
rm -rf "$APP_DIR.old"; [ -d "$APP_DIR" ] && mv "$APP_DIR" "$APP_DIR.old"
mv "$APP_DIR.new" "$APP_DIR"; rm -rf "$APP_DIR.old" "$TMP"
chown -R root:root "$APP_DIR"
# The app creates $DATA_DIR/secret.key (mode 0600, this user) on its first start. The installer never makes or
# prints a secret: SECRET_KEY stays unset below.
chown -R "$SVC_USER:$SVC_USER" "$DATA_DIR"
chmod 750 "$DATA_DIR"

# ---------------------------------------------------------------- config
# OpenRC sources this file as shell, so values are single-quoted: ADMIN_PASSWORD_HASH holds dollar signs.
add_setting() {  # add_setting FILE KEY VALUE COMMENT: only if KEY is not there yet
  grep -q "^$2=" "$1" 2>/dev/null && return 0
  case "$3" in *"'"*) echo "$2 may not contain a single quote."; exit 1 ;; esac
  printf "\n# %s\n%s='%s'\n" "$4" "$2" "$3" >> "$1"
  ADDED="${ADDED:-} $2"
}
[ -f "$CONF" ] || printf '# Gift Exchange settings. After editing: rc-service %s restart\n' "$NAME" > "$CONF"
add_setting "$CONF" EXCHANGE_PORT "$PORT" "Port gunicorn listens on. It binds 127.0.0.1 only: cloudflared in this container is the one way in."
add_setting "$CONF" APP_NAME "${APP_NAME:-Gift Exchange}" "Page title and home-screen name. Keep it neutral."
add_setting "$CONF" ADMIN_PASSWORD_HASH "${ADMIN_PASSWORD_HASH:-}" "Admin password hash from: echo 'a-password' | python3 /opt/exchange/manage.py hash-password. Empty = no admin sign-in."
# Holds the admin password hash, so root only: OpenRC runs as root and gives the service what it needs.
chmod 600 "$CONF"; chown root:root "$CONF"

# ---------------------------------------------------------------- service
cat > "$INITD" <<'EOF2'
#!/sbin/openrc-run
name="exchange"
description="Gift Exchange (Flask + gunicorn, loopback only)"
supervisor="supervise-daemon"
respawn_delay=5
respawn_max=10
respawn_period=600
command="/usr/bin/gunicorn"
command_user="exchange"
output_log="/var/log/exchange.log"
error_log="/var/log/exchange.log"

depend() { need net; after firewall; }

start_pre() {
  : ${EXCHANGE_PORT:=8770}
  command_args="--preload --workers 2 --threads 4 --timeout 60 --bind 127.0.0.1:${EXCHANGE_PORT} --chdir /opt/exchange --error-logfile /var/log/exchange.log app:app"
  export HOME=/var/lib/exchange DATA_DIR=/var/lib/exchange
  export EXCHANGE_PORT APP_NAME ADMIN_PASSWORD_HASH
  checkpath -f -o exchange:exchange -m 0640 /var/log/exchange.log
}
EOF2
chmod 755 "$INITD"

echo "==> Installing the nightly backup"
mkdir -p /etc/periodic/daily
install -m 755 "$APP_DIR/ops/exchange-backup" "$BACKUP_JOB"
rc-update add crond default >/dev/null 2>&1 || true
rc-service crond start >/dev/null 2>&1 || true

rc-update add "$NAME" default >/dev/null 2>&1 || true
rc-service "$NAME" start >/dev/null 2>&1 || true

echo "==> Waiting for the app"
i=0
until wget -qO- "http://127.0.0.1:$PORT/healthz" 2>/dev/null | grep -q ok; do
  i=$((i + 1))
  if [ "$i" -ge 20 ]; then
    echo "The service did not answer. Check: tail -n 40 $LOG"
    exit 1
  fi
  sleep 1
done

echo "==> Taking a first backup"
"$BACKUP_JOB" || echo "    (backup reported a problem; see /var/log/$NAME-backup.log)"

echo
echo "Gift Exchange is running on 127.0.0.1:$PORT (loopback only)."
[ -n "${ADDED:-}" ] && echo "Settings added to $CONF:$ADDED"
if [ -z "$(conf_val ADMIN_PASSWORD_HASH)" ]; then
  echo "No admin password yet: echo 'a-password' | python3 $APP_DIR/manage.py hash-password"
  echo "then put the result in $CONF (vim $CONF) as ADMIN_PASSWORD_HASH='...' and run: rc-service $NAME restart"
fi
echo "Point the Cloudflare Tunnel at http://127.0.0.1:$PORT (cloudflared in this container). No Access application."
exit 0
